package com.airesumebuilder.feature.notification.service;import com.airesumebuilder.common.exception.ResourceNotFoundException;import java.sql.*;import java.time.Instant;import java.util.List;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.*;import org.springframework.transaction.annotation.Transactional;
@Service public class NotificationService{private final NotificationRepository r;public NotificationService(NotificationRepository r){this.r=r;}@Transactional(readOnly=true)public List<Item>list(String e,boolean unread){return r.list(e,unread);}@Transactional public Item read(String e,long id){return r.read(e,id);}@Transactional public int readAll(String e){return r.readAll(e);}public record Item(long id,String type,String title,String body,String status,Instant readAt,Instant createdAt){} }
@Repository class NotificationRepository{private final JdbcTemplate j;NotificationRepository(JdbcTemplate j){this.j=j;}List<NotificationService.Item>list(String e,boolean unread){return j.query("SELECT n.* FROM notifications n JOIN users u ON u.id=n.user_id WHERE u.email=?"+(unread?" AND n.read_at IS NULL":"")+" ORDER BY n.created_at DESC",this::map,e);}NotificationService.Item read(String e,long id){if(j.update("UPDATE notifications n JOIN users u ON u.id=n.user_id SET n.status='READ',n.read_at=COALESCE(n.read_at,NOW(6)) WHERE u.email=? AND n.id=?",e,id)==0)throw new ResourceNotFoundException("Notification not found.");return j.query("SELECT n.* FROM notifications n JOIN users u ON u.id=n.user_id WHERE u.email=? AND n.id=?",this::map,e,id).getFirst();}int readAll(String e){return j.update("UPDATE notifications n JOIN users u ON u.id=n.user_id SET n.status='READ',n.read_at=COALESCE(n.read_at,NOW(6)) WHERE u.email=? AND n.read_at IS NULL",e);}private NotificationService.Item map(ResultSet r,int n)throws SQLException{Timestamp t=r.getTimestamp("read_at");return new NotificationService.Item(r.getLong("id"),r.getString("type"),r.getString("title"),r.getString("body"),r.getString("status"),t==null?null:t.toInstant(),r.getTimestamp("created_at").toInstant());}}
